changeSet.sql:
CREATE TABLE comment_likes (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    profile_id BIGINT NOT NULL,
    comment_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT COMMENT_LIKES_PROFILE_UQ UNIQUE (profile_id, comment_id),
    CONSTRAINT COMMENT_LIKES_PROFILE_FK FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
    CONSTRAINT COMMENT_LIKES_COMMENT_FK FOREIGN KEY (comment_id) REFERENCES comments(id) ON DELETE CASCADE
);

CREATE INDEX idx_comment_likes_profile ON comment_likes(profile_id);
CREATE INDEX idx_comment_likes_comment ON comment_likes(comment_id);
